/**
 * Unit tests for CategoryPlot.removeDomainMarker.
 */
public class CategoryPlot_removeDomainMarker_TriageGen0Test {

    private CategoryPlot plot;
    private Marker mockMarker;

    @Before
    public void setUp() {
        plot = new CategoryPlot();
        mockMarker = mock(Marker.class);
    }

    /**
     * Helper method to inject markers into the private maps using reflection.
     * Since the internal structure uses Maps of ArrayLists, we need to populate them.
     */
    @SuppressWarnings("unchecked")
    private void injectMarkers(Map<Integer, ArrayList<Marker>> foregroundMap, 
                               Map<Integer, ArrayList<Marker>> backgroundMap, 
                               int index, 
                               Layer layer, 
                               ArrayList<Marker> markers) throws Exception {
        Field fgField = CategoryPlot.class.getDeclaredField("foregroundDomainMarkers");
        fgField.setAccessible(true);
        Map<Integer, ArrayList<Marker>> fg = (Map<Integer, ArrayList<Marker>>) fgField.get(plot);

        Field bgField = CategoryPlot.class.getDeclaredField("backgroundDomainMarkers");
        bgField.setAccessible(true);
        Map<Integer, ArrayList<Marker>> bg = (Map<Integer, ArrayList<Marker>>) bgField.get(plot);

        if (layer == Layer.FOREGROUND) {
            fg.put(index, markers);
        } else {
            bg.put(index, markers);
        }
    }

    @Test
    public void testRemoveDomainMarker_Foreground_MarkersNull() throws Exception {
        // Testing branch: markers == null -> returns true
        // Using an index that doesn't exist in the map to simulate null return from get()
        boolean result = plot.removeDomainMarker(0, mockMarker, Layer.FOREGROUND, true);
        assertTrue("Should return true when markers list is null", result);
    }

    @Test
    public void testRemoveDomainMarker_Background_MarkersNull() throws Exception {
        // Testing branch: markers == null (Background) -> returns true
        boolean result = plot.removeDomainMarker(0, mockMarker, Layer.BACKGROUND, true);
        assertTrue("Should return true when markers list is null", result);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_RemoveSuccess_NotifyTrue() throws Exception {
        // Testing branch: removed && notify -> fireChangeEvent()
        // Note: fireChangeEvent() is internal, we verify return value
        int index = 1;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        injectMarkers(null, null, index, Layer.FOREGROUND, list);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Marker should be removed", result);
        assertTrue("List should be empty", list.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Foreground_RemoveSuccess_NotifyFalse() throws Exception {
        // Testing branch: removed && !notify
        int index = 1;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        injectMarkers(null, null, index, Layer.FOREGROUND, list);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, false);

        assertTrue("Marker should be removed", result);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_RemoveFailure() throws Exception {
        // Testing branch: removed is false
        int index = 1;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mock(Marker.class)); // Add a different marker
        injectMarkers(null, null, index, Layer.FOREGROUND, list);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertFalse("Should return false if marker not found", result);
        assertEquals("List size should remain 1", 1, list.size());
    }

    @Test
    public void testRemoveDomainMarker_Background_RemoveSuccess() throws Exception {
        // Testing branch: Background layer logic
        int index = 5;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mockMarker);
        injectMarkers(null, null, index, Layer.BACKGROUND, list);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.BACKGROUND, true);

        assertTrue("Should remove from background", result);
        assertTrue(list.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Background_RemoveFailure() throws Exception {
        // Testing branch: Background layer + failure
        int index = 5;
        ArrayList<Marker> list = new ArrayList<>();
        list.add(mock(Marker.class));
        injectMarkers(null, null, index, Layer.BACKGROUND, list);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.BACKGROUND, true);

        assertFalse("Should return false", result);
    }
}
